#include "ui/OrbaMirrorComponent.h"
#include <algorithm>
namespace jeff::daw {static constexpr char keyMap[]={'a','s','d','f','j','k','l',';'};OrbaMirrorComponent::OrbaMirrorComponent(Sink s):sink(std::move(s)){setWantsKeyboardFocus(true);setAccessible(true);setTitle("Playable Orba Mirror: A S D F J K L semicolon");}void OrbaMirrorComponent::setSnapshot(const OrbaMirrorSnapshot&s){snap=s;repaint();}void OrbaMirrorComponent::resized(){auto b=getLocalBounds().toFloat();layout=calculateOrbaLayout({b.getX(),b.getY(),b.getWidth(),b.getHeight()});juce::Rectangle<float>body(layout.centre.x-layout.bodyRadius,layout.centre.y-layout.bodyRadius,layout.bodyRadius*2,layout.bodyRadius*2);for(int i=0;i<8;++i){paths[i].clear();paths[i].addPieSegment(body,layout.pads[i].startAngle,layout.pads[i].endAngle,layout.innerRadius/layout.bodyRadius);}}void OrbaMirrorComponent::paint(juce::Graphics&g){g.setColour(juce::Colour(0xff080b11));g.fillEllipse(layout.centre.x-layout.bodyRadius,layout.centre.y-layout.bodyRadius,layout.bodyRadius*2,layout.bodyRadius*2);for(int i=0;i<8;++i){auto v=std::max(snap.pads[i].intensity,snap.pads[i].pressure);g.setColour(juce::Colour::fromHSV(.55f+i*.035f,.75f,.25f+.7f*v,1.0f));g.fillPath(paths[i]);g.setColour(snap.pads[i].held?juce::Colours::white:juce::Colour(0xff526070));g.strokePath(paths[i],juce::PathStrokeType(snap.pads[i].held?3.f:1.f));g.setColour(juce::Colours::white);g.drawText(juce::String(i+1),(int)layout.pads[i].centre.x-15,(int)layout.pads[i].centre.y-10,30,20,juce::Justification::centred);}g.setColour(juce::Colour(0xff202632));g.fillEllipse(layout.centre.x-layout.innerRadius,layout.centre.y-layout.innerRadius,layout.innerRadius*2,layout.innerRadius*2);g.setColour(juce::Colours::white);g.setFont(juce::FontOptions(16,juce::Font::bold));g.drawText(snap.modelLabel,(int)(layout.centre.x-layout.innerRadius),(int)(layout.centre.y-14),(int)(layout.innerRadius*2),28,juce::Justification::centred);}int OrbaMirrorComponent::hit(juce::Point<float>p)const{for(int i=0;i<8;++i)if(paths[i].contains(p.x,p.y))return i;return-1;}void OrbaMirrorComponent::on(int p,float v){if(p>=0)sink(PerformanceEvent::noteOn(0,p,v,juce::Time::currentTimeMillis()));}void OrbaMirrorComponent::off(int p){if(p>=0)sink(PerformanceEvent::noteOff(0,p,juce::Time::currentTimeMillis()));}void OrbaMirrorComponent::mouseDown(const juce::MouseEvent&e){grabKeyboardFocus();mousePad=hit(e.position);on(mousePad,e.pressure>0?e.pressure:.8f);}void OrbaMirrorComponent::mouseDrag(const juce::MouseEvent&e){if(mousePad>=0)sink(PerformanceEvent::expression(0,0,mousePad,ExpressionKind::pressure,e.pressure>0?e.pressure:.75f,0,juce::Time::currentTimeMillis()));}void OrbaMirrorComponent::mouseUp(const juce::MouseEvent&){off(mousePad);mousePad=-1;}bool OrbaMirrorComponent::keyPressed(const juce::KeyPress&k){auto c=juce::CharacterFunctions::toLowerCase((juce::juce_wchar)k.getKeyCode());for(int i=0;i<8;++i)if(c==keyMap[i]){if(!keys[i]){keys[i]=true;on(i,.82f);}return true;}return false;}bool OrbaMirrorComponent::keyStateChanged(bool){bool h=false;for(int i=0;i<8;++i)if(keys[i]&&!juce::KeyPress::isKeyCurrentlyDown(keyMap[i])){keys[i]=false;off(i);h=true;}return h;}}
